#[inline(always)]
pub(crate) fn tan_kernel_f64(x: f64) -> f64 {
    let ax = x.abs();
    let t = if ax <= TAN_SEG_BOUNDS_F64[0] {
        let z = ax * ax;
        ax + ax * z * eval_horner_f64_slice(z, &COEFFS64_SEG0)
    } else if ax <= TAN_SEG_BOUNDS_F64[1] {
        let z = ax * ax;
        ax + ax * z * eval_horner_f64_slice(z, &COEFFS64_SEG1)
    } else if ax <= TAN_SEG_BOUNDS_F64[2] {
        let z = ax * ax;
        ax + ax * z * eval_horner_f64_slice(z, &COEFFS64_SEG2)
    } else {
        let z = ax * ax;
        ax + ax * z * eval_horner_f64_slice(z, &COEFFS64_SEG2)
    };
    if x.is_sign_negative() {
        -t
    } else {
        t
    }
}

#[inline(always)]
pub(crate) fn tan_kernel_estrin_f64(x: f64) -> f64 {
    let ax = x.abs();
    let t = if ax <= TAN_SEG_BOUNDS_F64[0] {
        let z = ax * ax;
        let estrin_0_0 = COEFFS64_SEG0[0] + COEFFS64_SEG0[1] * z;
        let estrin_0_1 = COEFFS64_SEG0[2] + COEFFS64_SEG0[3] * z;
        let estrin_0_2 = COEFFS64_SEG0[4] + COEFFS64_SEG0[5] * z;
        let estrin_0_3 = COEFFS64_SEG0[6] + COEFFS64_SEG0[7] * z;
        let estrin_0_4 = COEFFS64_SEG0[8] + COEFFS64_SEG0[9] * z;
        let estrin_0_5 = COEFFS64_SEG0[10] + COEFFS64_SEG0[11] * z;
        let estrin_pow_1 = z * z;
        let estrin_1_0 = estrin_0_0 + estrin_0_1 * estrin_pow_1;
        let estrin_1_1 = estrin_0_2 + estrin_0_3 * estrin_pow_1;
        let estrin_1_2 = estrin_0_4 + estrin_0_5 * estrin_pow_1;
        let estrin_pow_2 = estrin_pow_1 * estrin_pow_1;
        let estrin_2_0 = estrin_1_0 + estrin_1_1 * estrin_pow_2;
        let estrin_pow_3 = estrin_pow_2 * estrin_pow_2;
        let estrin_3_0 = estrin_2_0 + estrin_1_2 * estrin_pow_3;
        ax + ax * z * estrin_3_0
    } else if ax <= TAN_SEG_BOUNDS_F64[1] {
        let z = ax * ax;
        let estrin_0_0 = COEFFS64_SEG1[0] + COEFFS64_SEG1[1] * z;
        let estrin_0_1 = COEFFS64_SEG1[2] + COEFFS64_SEG1[3] * z;
        let estrin_0_2 = COEFFS64_SEG1[4] + COEFFS64_SEG1[5] * z;
        let estrin_0_3 = COEFFS64_SEG1[6] + COEFFS64_SEG1[7] * z;
        let estrin_0_4 = COEFFS64_SEG1[8] + COEFFS64_SEG1[9] * z;
        let estrin_0_5 = COEFFS64_SEG1[10] + COEFFS64_SEG1[11] * z;
        let estrin_0_6 = COEFFS64_SEG1[12] + COEFFS64_SEG1[13] * z;
        let estrin_pow_1 = z * z;
        let estrin_1_0 = estrin_0_0 + estrin_0_1 * estrin_pow_1;
        let estrin_1_1 = estrin_0_2 + estrin_0_3 * estrin_pow_1;
        let estrin_1_2 = estrin_0_4 + estrin_0_5 * estrin_pow_1;
        let estrin_1_3 = estrin_0_6 + COEFFS64_SEG1[14] * estrin_pow_1;
        let estrin_pow_2 = estrin_pow_1 * estrin_pow_1;
        let estrin_2_0 = estrin_1_0 + estrin_1_1 * estrin_pow_2;
        let estrin_2_1 = estrin_1_2 + estrin_1_3 * estrin_pow_2;
        let estrin_pow_3 = estrin_pow_2 * estrin_pow_2;
        let estrin_3_0 = estrin_2_0 + estrin_2_1 * estrin_pow_3;
        ax + ax * z * estrin_3_0
    } else if ax <= TAN_SEG_BOUNDS_F64[2] {
        let z = ax * ax;
        let estrin_0_0 = COEFFS64_SEG2[0] + COEFFS64_SEG2[1] * z;
        let estrin_0_1 = COEFFS64_SEG2[2] + COEFFS64_SEG2[3] * z;
        let estrin_0_2 = COEFFS64_SEG2[4] + COEFFS64_SEG2[5] * z;
        let estrin_0_3 = COEFFS64_SEG2[6] + COEFFS64_SEG2[7] * z;
        let estrin_0_4 = COEFFS64_SEG2[8] + COEFFS64_SEG2[9] * z;
        let estrin_0_5 = COEFFS64_SEG2[10] + COEFFS64_SEG2[11] * z;
        let estrin_0_6 = COEFFS64_SEG2[12] + COEFFS64_SEG2[13] * z;
        let estrin_pow_1 = z * z;
        let estrin_1_0 = estrin_0_0 + estrin_0_1 * estrin_pow_1;
        let estrin_1_1 = estrin_0_2 + estrin_0_3 * estrin_pow_1;
        let estrin_1_2 = estrin_0_4 + estrin_0_5 * estrin_pow_1;
        let estrin_1_3 = estrin_0_6 + COEFFS64_SEG2[14] * estrin_pow_1;
        let estrin_pow_2 = estrin_pow_1 * estrin_pow_1;
        let estrin_2_0 = estrin_1_0 + estrin_1_1 * estrin_pow_2;
        let estrin_2_1 = estrin_1_2 + estrin_1_3 * estrin_pow_2;
        let estrin_pow_3 = estrin_pow_2 * estrin_pow_2;
        let estrin_3_0 = estrin_2_0 + estrin_2_1 * estrin_pow_3;
        ax + ax * z * estrin_3_0
    } else {
        let z = ax * ax;
        let estrin_0_0 = COEFFS64_SEG2[0] + COEFFS64_SEG2[1] * z;
        let estrin_0_1 = COEFFS64_SEG2[2] + COEFFS64_SEG2[3] * z;
        let estrin_0_2 = COEFFS64_SEG2[4] + COEFFS64_SEG2[5] * z;
        let estrin_0_3 = COEFFS64_SEG2[6] + COEFFS64_SEG2[7] * z;
        let estrin_0_4 = COEFFS64_SEG2[8] + COEFFS64_SEG2[9] * z;
        let estrin_0_5 = COEFFS64_SEG2[10] + COEFFS64_SEG2[11] * z;
        let estrin_0_6 = COEFFS64_SEG2[12] + COEFFS64_SEG2[13] * z;
        let estrin_pow_1 = z * z;
        let estrin_1_0 = estrin_0_0 + estrin_0_1 * estrin_pow_1;
        let estrin_1_1 = estrin_0_2 + estrin_0_3 * estrin_pow_1;
        let estrin_1_2 = estrin_0_4 + estrin_0_5 * estrin_pow_1;
        let estrin_1_3 = estrin_0_6 + COEFFS64_SEG2[14] * estrin_pow_1;
        let estrin_pow_2 = estrin_pow_1 * estrin_pow_1;
        let estrin_2_0 = estrin_1_0 + estrin_1_1 * estrin_pow_2;
        let estrin_2_1 = estrin_1_2 + estrin_1_3 * estrin_pow_2;
        let estrin_pow_3 = estrin_pow_2 * estrin_pow_2;
        let estrin_3_0 = estrin_2_0 + estrin_2_1 * estrin_pow_3;
        ax + ax * z * estrin_3_0
    };
    if x.is_sign_negative() {
        -t
    } else {
        t
    }
}

