#[inline(always)]
pub(crate) fn reconstruct_tan_f64(q: u8, t: f64) -> f64 {
    match q & 1 {
        0 => t,
        1 => -1.0_f64 / t,
        _ => unreachable!(),
    }
}

#[inline(always)]
pub(crate) fn reconstruct_tan_f32(q: u8, t: f32) -> f32 {
    match q & 1 {
        0 => t,
        1 => -1.0_f32 / t,
        _ => unreachable!(),
    }
}

#[inline(always)]
fn reconstruct_tan_f16(q: u8, t: f16) -> f16 {
    let tf = t as f32;
    let y = match q & 1 {
        0 => tf,
        1 => -1.0_f32 / tf,
        _ => unreachable!(),
    };
    y as f16
}

#[inline(always)]
fn reconstruct_tan_f128(q: u8, t: f128) -> f128 {
    match q & 1 {
        0 => t,
        1 => -1.0_f128 / t,
        _ => unreachable!(),
    }
}

