#[inline]
pub fn tan(x: f64) -> f64 {
    if !x.is_finite() {
        return f64::NAN;
    }
    let (r, q) = rem_pio2_tan_f64(x);
    if q & 1 == 0 && r.abs() <= 0.003_f64 {
        return reconstruct_tan_f64(q, k_tan_f64(apply_policy_tan_f64(r)));
    }
    let s = crate::trig::sin::sin(r);
    let c = crate::trig::cos::cos(r);
    if q & 1 == 0 {
        s / c
    } else {
        -c / s
    }
}

#[inline]
pub fn tanl(x: f128) -> f128 {
    if !x.is_finite() {
        return f128::NAN;
    }
    let (r, q) = rem_pio2_tan_f128(x);
    let s = crate::trig::sin::sinl(r);
    let c = crate::trig::cos::cosl(r);
    let quotient = if q & 1 == 0 { s / c } else { -c / s };

    let doubled = 2.0_f128 * r;
    let sin_doubled = crate::trig::sin::sinl(doubled);
    let one_plus_cos_doubled = 1.0_f128 + crate::trig::cos::cosl(doubled);
    let identity = if q & 1 == 0 {
        sin_doubled / one_plus_cos_doubled
    } else {
        -one_plus_cos_doubled / sin_doubled
    };

    if !quotient.is_finite() || !identity.is_finite() {
        quotient
    } else {
        quotient + 0.5_f128 * (identity - quotient)
    }
}

#[inline]
pub fn tanf(x: f32) -> f32 {
    if !x.is_finite() {
        return f32::NAN;
    }
    let (r, q) = rem_pio2_tan_f32(x);
    reconstruct_tan_f32(q, k_tan_f32(apply_policy_tan_f32(r)))
}

#[inline]
pub fn tans(x: f16) -> f16 {
    if !x.is_finite() {
        return f16::NAN;
    }
    let (r, q) = rem_pio2_tan_f16(x);
    reconstruct_tan_f16(q, k_tan_f16(r))
}

#[cfg(feature = "mx")]
#[inline]
pub fn tan_fp4_e2m1(x: Fp4E2M1) -> Fp4E2M1 {
    let x32 = f32::from(x);
    if !x32.is_finite() {
        return Fp4E2M1::from(f32::NAN);
    }
    Fp4E2M1::from(tanf(x32))
}

